return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Basque','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 14:34+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'eu','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" gorde da.','"%1$s" created. %2$d template updated.'=>'"%s" sortu da. %d txantiloia eguneratu da.' . "\0" . '"%s" sortu da. %d txantiloia eguneratu da.','"%s" created.'=>'"%s" sortu da.','%d language not yet linked'=>'%d hizkuntza oraindik lotu gabe' . "\0" . '%d hizkuntza oraindik lotu gabe','%d link updated.'=>'%d esteka eguneratu da.' . "\0" . '%d esteka eguneratu da.','%d locale pack installed.'=>'%d locale pack instalatuta.' . "\0" . '%d locale pack instalatuta.','%d navigation reference updated.'=>'%d nabigazio erreferentzia eguneratu da.' . "\0" . '%d nabigazio erreferentzia eguneratu da.','%d part reference updated.'=>'%d zatiko erreferentzia eguneratu da.' . "\0" . '%d zatiko erreferentzia eguneratu da.','%s Archive'=>'%s Artxiboa','(avg %.1f hits/block)'=>'(batez besteko %.1f iriste/blokea)','(avg %.1f hits/entry)'=>'(batez besteko %.1f eraso/erregistro)','(disabled)'=>'(ezgaituta)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} ez zuen ordezkagarri dauden loturarik — berriro eskaneatu ikusteko)}','.txt file(s) in the directory'=>'Direktorioan .txt fitxategi(a)','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizatutako txantiloi(ak) &#8220;%2$s&#8221; gaiarekin datu-basean gordeak daude, baina une honetan ez daude aktibo. Aktibatu berriro gaia berreskuratuz gero, aktibo egongo dira. Zure itzulpenak gaia berri horretara eramateko, berriro sortu <strong>Ezarpenak → Lingua Forge → Router → FSE eskema</strong> bidez.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> auto-konpondu daitezkeen lotura','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> eskuz berrikusi behar diren lotura','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> bide zahar(ra)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> txantiloi arazo(ak)','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Only konpilatutako .mo fitxategiak onartzen dira. Fitxategiak {textdomain}-{locale}.mo eredua jarraitu behar du. Fitxategi batek izen bera badu beste batekin, ordeztuko du.','Action'=>'Ekintza','Actions'=>'Ekintzak','active'=>'aktiboa','Active Languages'=>'Hizkuntzak aktiboak','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Hizketan dauden hizkuntzak: gehitu nahi dituzun hizkuntza bakoitza. Hizkuntza bakoitzak URL aurrizki edo azpihostalari bat eta hreflang etiketa bat jasoko du orrialdearen &lt;head&gt;-n.','Active Provider'=>'Hornitzaile aktiboa','Add entry'=>'Gehitu sarrera','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Gehitu jarraibideak zirriborroa hobetu - adibidez, laburtu, laburpen atala gehitu, erabili erregistro formalagoa, FAQ blokea gehitu…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Goratu eskakizunak, adibidez, laburtu, laburpen atala gehitu, erabili formaleagoa...','Add new entry'=>'Gehitu sarrera berria','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Gehitu termino bat lerro bakoitzean. Biak, iturriko terminoa eta helburuko itzulpena, beharrezkoak dira. Pareta hizkuntzak zehazten du zein itzulpen lanetan aplikatzen den muga hori.','Adds a link to the home page so visitors can browse in their language.'=>'Bisitariek beren hizkuntzan nabigatu ahal izateko esteka bat gehitzen du.','Administrators only (manage_options)'=>'Administratzaileak bakarrik (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Hizkuntza nagusia aldatu ondoren, permalinka guztiak bota (beheko atala) URL bideraketa eguneratzeko.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL egitura ezarpenak aldatu ondoren (bidea aurrebista ↔ azpigunea), beti bisitatu Ezarpenak → Permalinks eta sakatu Gorde Aldaketak birkargatzeko erreibatu arauak.','AI Behaviour Preset'=>'AI Portaera Aurrebista','AI cache cleared. %d entry was removed.'=>'AI cachea garbitu da. %d sarrera ezabatu da.' . "\0" . 'AI cachea garbitu da. %d sarrera ezabatu dira.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Cache: AI erantzunen cachea eta eraso kopuruen zerrenda. Garbitu cache osoa edo post baten sarrera bakarra. Erabili "Garbitu" itzulpen aldaketa probatu aurretik — cacheko emaitzak itzultzen dira, AI preset edo modelo aldatzen duzun arte, cacheko sarrera kendu arte.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI ezaugarriak aukerakoak dira. Hizkuntzen bideraketa, hreflang, hizkuntzaren switcher eta itzulpen taldea sistema guztiak lan egiten dute hornitzailearen konfigurazio gabe.','AI Limits & Security'=>'AI Muga eta Segurtasuna','AI provider returned an empty response.'=>'AI hornitzaileak erantzun hutsa eman du.','AI Usage'=>'AI Erabilera','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Helburu 120–160 karakteretan. Utzi hutsik zatia erabili nahi baduzu.','All time'=>'Denbora guztian','Allow editors to lock individual blocks'=>'Baimendu editoreek bloke bana blokeatzea','Allow Gutenberg template-editing mode on post screens'=>'Baimendu Gutenberg-eko txantiloi editatzeko modua mezularitza pantailetan','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Era berean, ezabatu hizkuntza esleipenak, itzulpen harremanak, meta deskribapenak, glosarioa eta Itzulpen Memoria plugin-a desinstalatzen denean.','Also generate meta description'=>'Era berean, sortu meta deskribapena','Alternative (server-side):'=>'Alternatiba (zerbitzarian):','An unknown error occurred.'=>'Errore ezezaguna gertatu da.','and'=>'eta','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'edozein','API calls saved by cache'=>'API deien gordetakoak cache bidez','API Key'=>'API Giltza','API Keys'=>'API giltzak','API Keys Tab'=>'API Gakoen Fitxa','API Response Cache'=>'API Erantzun Cachea','Applied ✓'=>'Aplikatua ✓','Apply failed — please try again.'=>'Aplikazioa huts egin du — mesedez saiatu berriro.','Apply to Block'=>'Aplikatu blokean','Apply to Editor'=>'Aplikatu Editoreari','Apply to Footnote'=>'Aplikatu ohar notan','Apply to Meta Description'=>'Aplikatu Meta Deskribapenera','Apply translation'=>'Aplikatu itzulpena','Applying…'=>'Aplikatzen…','Approximate size'=>'Tamaina hurbila','Archive'=>'Artxiboa','Archive: %s'=>'Artxiboa: %s','Authors and above (edit_published_posts)'=>'Egileak eta gehiago (edit_published_posts)','Behavior'=>'Jokabidea','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Jokabidea: aukeratu AI preset (Literal, Balanced, Creative), gehitu webguneko prompt-instrukzio pertsonalizatuak, gaituta edo desgaituta utzi automatikoki postaren gordailuaren itzulpena, eta konfiguratu Itzulpen Memoria.','Block Content'=>'Blokearen edukia','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Uneko orria bere jatorrizko hizkuntzan erakusten du, ez dagoelako itzulpenik bisitariaren hizkuntzarako. Lingua Forge router-aren LINGUAFORGE_LANG_FALLBACK_ACTIVE seinalearen bidez kontrolatzen da — ez du ezer emititzen eskaeraren hizkuntzarako itzulpenik badago.','Block Editor'=>'Bloke Editorea','block keywordfallback'=>'falta','block keywordi18n'=>'i18n','block keywordlanguage'=>'hizkuntza','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'itzulpena','Block locking'=>'Blokearen blokeatzea','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Ezarritako blokeak post moten pertsonalizatuak. Erabili Itzuli botoia hizkuntza bertsioa sortzeko. Edukia itzulita hemen gordetzen da eta CPT post batean kopiatu daiteke blokea editorearen Pattern inserter-etik edo erabil daiteke Pattern Sinked (Erabilgarri Blokea) hasteko.','block titleMissing Translation Notice'=>'Hitzordua falta den oharraren jakinarazpena','Block translation reuses'=>'Bloke itzulpenaren erabilerak','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Bloke mailako itzulpen cachea post guztietan partekatua. Gaituta, bloke berdinak (marko bera, hizkuntza pareta, eta glosarioa) memoriaetik ematen dira AI berriro deitu beharrik izan gabe. Konfiguratu Ezarpenak → Jokabidea.','Browser language redirect'=>'Nabigatzailearen hizkuntzaren birzirkulazioa','Built-in preset instructions:'=>'Prestatutako ezarpenak: ','Bulletize (•-prefixed)'=>'Buleta (•-rekin hasita)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache itzulpen baliokideak bloke mailan, eduki erabili daitekeenak (oina, alboak, akordeoiak, lege-oinarriak) API deia egin gabe. Aktibatuta, itzulpen fluxuak post bakoitza bloketan banatzen du, cache-an bilatzen du eta blokez kanpokoak AI-ra bidaltzen ditu eskaera batean. Glosario editaketak eta Betetze aurreko aldaketak automatikoki baliogabetzen dituzte cacheko itzulpenak. Estatistikak ikusi eta cachea garbitu Mantentzean.','cached'=>'Gordeta','Cached API responses'=>'Cacheko API erantzunak','Cached block translations'=>'Cacheko bloke itzulpenak','Cancel'=>'Ezeztatu','Cannot determine target language from slug.'=>'Ezin da helburu hizkuntza slug-etik zehaztu.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Murriztu AI erabilera muga eta baimendu erabiltzaile rol batzuk AI bidezko deien kostuak kontrolatzeko. Erabiltzaile bakoitzeko tasa-muga gainditzen du (30 eskaera / minutua, kodean ezarrita), eta bakarrik erabiltzaile bakarraren abiadura kontrolatzen du.','chars'=>'karaktereak','Chunk translated'=>'Zati itzuli','Chunk translated to:'=>'Zati itzuli da:','Clear'=>'Garbitu','Clear All'=>'Garbitu guztiak','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Garbitu AI cacheko emaitza guztiak? Etorkizuneko eskaerak API deia berriro eragingo du cachea berritzen den arte.','Clear API Response Cache'=>'Garbitu API Erantzun Cachea','Clear Debug Files'=>'Garbitu Debug Fitxategiak','Clear hints'=>'Garbitu aholkuak','Clear input'=>'Garbitu sarrera','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Garbitu Itzulpen Memoria osoa? Etorkizuneko itzulpenek cachea berriro eraikiko dute.','Clear Translation Memory'=>'Garbitu Itzulpen Memoria','Close'=>'Itxi','Close language panel'=>'Itzuli panel hizkuntza','Close popover'=>'Itxi popover','Compliance Preset'=>'Betetze aurrekoa','Content generated'=>'Edukia sortu da','Content Generator'=>'Eduki Sortzailea','Content ready'=>'Edukia prest dago','Contributors and above — default (edit_posts)'=>'Garatzaileak eta gehiago — lehenetsia (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Nola kontrolatu edukiaren kantitatea AIra bidaltzen dena eta erantzunaren tamaina. Utzi hutsik, balio lehenetsia erabiltzeko. Handitu balioak orri handiak moztu badira; jaitsi API kostuak murrizteko.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI Eduki Sortzailearen token aurrekontua eta sarrera mugak kontrolatzen ditu. Utzi eremuak hutsik, ezarritako balioekin erabiltzeko.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kudeatzen du zer gertatzen den administratzaileak plugin-a ezabatzen duenean Plugins → Installed Plugins → Delete. Pluginaren ezarpenak eta AI cache-ak beti ezabatzen dira. Hizkuntza esleipenak eta itzulpen harremanak mantentzen dira lehenetsita, beraz, desinstalazio edo berrinstalazio batetik bertara itzuli daiteke.','Conversational'=>'Egunerokoa','Copied ✓'=>'Kopiatu ✓','Copy'=>'Kopiatu','Copy markup'=>'Kopiatu markaketa','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Kopiatu emaitza eta itsatsi behar den lekuan (adibidez, zuzenean azpiko eremuan).','Copy to safe storage'=>'Kopiatu segurtasun gunean','Could not add entry: source term and target term are required.'=>'Ezin izan da sarrera gehitu: iturri terminoa eta helburu terminoa beharrezkoak dira.','Could not copy the file. Check that the uploads folder is writable.'=>'Ez da fitxategia kopiatzen. Egiaztatu upload karpeta idazgarria dela.','Could not instantiate the provider.'=>'Ezin izan da hornitzailea sortu.','Could not save the file. Check that the uploads folder is writable.'=>'Ez da fitxategia gorde. Egiaztatu upload karpeta idazgarria dela.','Could not save the glossary entry.'=>'Ezin izan da glossario sarrera gorde.','CPT Block Patterns'=>'CPT Bloke Patternak','Create'=>'Sortu','Create missing'=>'Sortu gabeak','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'"%s" post motarako itzulpenak sortzea aktibo dagoen integrazio bat behar du. Mesedez, ziurtatu integrazioa instalatuta eta aktiboa dagoela.','Creating…'=>'Sortzen…','Creative / Marketing'=>'Sortzailea / Marketina','Creative / Marketing instructions'=>'Kreatiboa / Marketin argibideak','Current content (will be overwritten)'=>'Uneko edukia (gaur egun ordezkatuko da)','Current title'=>'Uneko izenburua','Current: {current}'=>'Unekoa: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Une honetan %s konstantea heredatzen da. Hemen balioa hautatzeak gaindituko du.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Une honetan ez da erabiltzen, post-aren atributuaren placeholder-ak (wp:details laburpen eremuak, etab.) erabiltzen dituztenak — existitzen den itzulpen bide bakarrean pasatzen dira.','Currently:'=>'Unean','Custom'=>'Pertsonalizatua','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'AI egutegiko kuota bete da (%1$d eskaera). Resetatzen da %2$s UTC-tan.','Daily request limit'=>'Eguneko eskaera muga','Debug Files'=>'Debug Fitxategiak','Debug files cleared. %d file was removed.'=>'Debug fitxategiak garbitu dira. %d fitxategi bat kendu da.' . "\0" . 'Debug fitxategiak garbitu dira. %d fitxategi kendu dira.','Debug logging'=>'Debug log-ak','Debug logging disabled.'=>'Debug log-ak desaktibatuta daude.','Debug logging enabled.'=>'Debug log-ak aktibatuta daude.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: gaitu debug erregistroa AI promptak eta API erantzunak lokaleko fitxategi batean harrapatzeko. Desgaitu arazoak konpontzeko — debug moduak fitxategi bat idazten du AI eskaera bakoitzean.','Delete'=>'Ezabatu','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Ezabatu debug direktorioan dauden .txt fitxategi guztiak? Direktorioa bera geratuko da, etorkizuneko debug idatziak garbi iritsi daitezen.','Delete all files for this override (both .mo and .po)?'=>'Ezabatu fitxategi guztiak ordezkaritza honetan (biak .mo eta .po)?','Delete content data on uninstall'=>'Ezabatu edukien datuak desinstalazioan','Delete this glossary entry?'=>'Ezabatu glossario sarrera hau?','Describe what to write — topic, key points, structure…'=>'Deskribatu zer idatzi behar den — gaia, gako puntuak, egitura…','Directory'=>'Direktorioa','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Desgaitu prompt tuning-ean edo behar duzunean AI hornitzailearengana eskaerak iristeko. Desgaituak cacheko sarrera ezabatzen ez ditu, berriro aktibatzeak berreskuratzen ditu. API gastua handitzea espero da, batez ere gune busyetan, desgaituta dagoenean.','Display'=>'Erakutsi','Displays the Lingua Forge language switcher.'=>'Lingua Forge hizkuntza aldatzailearen pantaila erakusten du.','Documentation'=>'Dokumentazioa','Done'=>'Eginda','Done — {done} of {total} post(s) fixed.'=>'Eginda — {done} post eta orri {total} konponduta.','Down'=>'Behera','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Deskargatu eta instalatu WordPressen hizkuntza pakete nagusia WordPress.org-etik. Instalatu ondoren, locale-a URL bidegurutze eta AI itzulpen lanerako erabilgarri izango da. Eskuragarri dauden hizkuntzen zerrenda eskakizunaren arabera lortzen da — sakatu beheko botoia kargatzeko.','Dropdown direction'=>'Dropdown norabidea','Editors and above (edit_others_posts)'=>'Editoreak eta gehiago (edit_others_posts)','Enable API response caching'=>'Gaitu API erantzunen cachea','Enable block-level translation cache reuse across posts'=>'Bloke mailako itzulpen cache erabili beste postetan','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Sartu zure API gakoa gutxienez AI hornitzaile batean. Gakoak AES-256-GCM erabiliz enkriptatzen dira atsedenaldian, gune bereziko sekretu batekin (LINGUAFORGE_SECRET). Ez partekatu datu-base esportazioak sekretua lehenengo birrortzen ez baduzu.','environment variable'=>'ingurune aldagaia','Error'=>'Errorea','Expand'=>'Zabaldu','Expected: {expected}'=>'Itxaron: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Gida osagarria — tonua, estiloa, murrizketak, helburu publikoa…','Extra guidance — tone, style, constraints…'=>'Gida osagarria — tonua, estiloa, murrizketak…','Failed. Please try again.'=>'Huts egin du. Saiatu berriro.','Feature'=>'Ezaugarri','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Ezaugarriak bi mailatan banatzen dira. Sartu bakoitzaren identifikadore zehatza eta hornitzailearen izena. Utzi hutsik, lehenetsia erabiltzeko. Aktibo den hornitzailearen modeloak bakarrik deitzen dira exekuzioan — besteak aurretik konfiguratu behar dira aldatzeko.','File copied to safe storage successfully.'=>'Fitxategia arrakastaz kopiatuta segurtasun gunean.','Files'=>'Fitxategiak','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Fitxategiak beheko direktorian kokatzen dira. Itzulpen arazoak diagnostikatzeko erabilgarria — itzali behar duzu behar duzuna lortu arte, bestela fitxategiak handitzen dira. Hau behartu dezakezu wp-config.php-tik `define( \'LINGUAFORGE_AI_DEBUG\', true );` erabiliz, toggle hori gainetik.','Filter'=>'Filtroa','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtratu linguaforge_debug_dir erabiliz, debug irteera ezkutuko kokapen batera bideratzeko.','Fix'=>'Konpondu','Fix All'=>'Konpondu Guztiak','Fix all links'=>'Konpondu estekak guztiak','Fix all parts'=>'Konpondu atal guztiak','Fix Links'=>'Aldatu Estekak','Fix Nav'=>'Aldatu Nabigazioa','Fix Parts'=>'Aldatu Zatiak','Fix Template'=>'Konpondu Txantiloa','Fixing {n} / {total}…'=>'{n} / {total} konpontzen…','Fixing…'=>'Konpontzen…','Flush Permalink Rules'=>'Bota Permalink Arauak','Flush Permalinks'=>'Bota Permalinks','Footnote Content'=>'Ohar notaren edukia','footnote(s) translated — applied together with content.'=>'Azpi-oinak itzuli dira — edukiarekin batera aplikatuta.','Footnotes'=>'Azpi-oinak','Footnotes payload (advanced)'=>'Ohar zinta ( aurreratua)','Forbidden'=>'Aurreikusi gabe','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Aurkitutako {parts} {total} postetan eta {scanned} aztertu direnetan {lang} hizkuntzarako.','From'=>'Nondik','Front Page'=>'Lehentasuna Orria','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE lokalizazioa: eskema, itzuli, eta konpondu estekak Full Site Editing txantiloi eta zatietan zuzenean taula honetan.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktiboen gaian oinarritutako FSE txantiloiak. Sortu eta pertsonalizatu Webgune Editorean.','Full Article'=>'Artikulu osoa','Full post'=>'Post osoa','General'=>'Orokorra','Generate'=>'Sortu','Generate Content'=>'Sortu Edukia','Generate content…'=>'Edukia sortu…','Generate Excerpt'=>'Sortu Aipamena','Generate Meta Description'=>'Sortu Meta Deskribapena','Generated Content'=>'Sortutako Edukia','Generated meta description'=>'Sortutako meta deskribapena','Generating…'=>'Sortzen…','Generation failed.'=>'Sortzea huts egin da.','Getting started'=>'Hasi','Global AI preset'=>'AI aurrekoa globala','Global default (%s)'=>'Nazioarteko lehenetsia (%s)','Glossary'=>'Glosario','Glossary entry added.'=>'Glossario sarrera gehitu da.','Glossary entry removed.'=>'Glossario sarrera ezabatu da.','Glossary Tab'=>'Glosarioaren Fitxa','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Ezkutatu','Hints'=>'Gomendioak','Home link text'=>'Hasierako estekaren testua','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Itzulpenan nola agertu behar duen. Iturri terminoa berdin gordetzeko AIri instrukzioa emateko, balio bera eman itzultzeko.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikono + etiketa','Icon only'=>'Ikono bakarra','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Egiaztatzen baduzu, plugin-a desinstalatzen duzunean, hizkuntza esleipen guztiak, itzulpen harremanak, meta deskribapenak, orrialdeko aurresetak, AI glosarioa eta Itzulpen Memoria betirako ezabatuko dira gune honetan. Hau ezin da desegin. Ez egiaztatu, gunean aniztasun hizkuntzak guztiz ezabatu nahi baduzu.','Improve writing'=>'Hobetu idazketa','Informative'=>'Informativo','Input tokens'=>'Sarrerako tokenak','Install'=>'Instalatu','Install a Language'=>'Hizkuntza bat instalatu','Installing…'=>'Instalatzen…','Instructions (optional)'=>'Argibideak (aukerakoa)','Instructions / key points'=>'Argibideak / gako puntuak','Integration API'=>'Integrazio API','Internal Link Fixer'=>'Barneko Lotura Konpontzailea','Introduction only'=>'Sarrera soil','Invalid file reference.'=>'Fitxategi erreferentzia baliogabea.','Invalid filename.'=>'Fitxategi izenburu baliogabea.','Invalid language.'=>'Hizkuntza baliogabea.','Invalid locale code.'=>'Hizkuntza kode baliogabea.','Invalid or primary language.'=>'Hizkuntza baliogabea edo lehenetsia.','Invalid post type.'=>'Post motaren errorea.','Invalid template part.'=>'Txantiloia zatia baliogabea.','Invalid template type.'=>'Txantiloia mota baliogabea.','Key points, ideas, or structure to build from…'=>'Puntu nagusiak, ideiak edo eraikitzeko egitura...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Giltzak AES-256-CBC enkriptatzen dira WordPress datu-basean gordetzeko. Enkriptazio sekretua zure WordPress autentifikazio gatz-iturrietatik dator (wp-config.php), beraz, testu hutseko giltzak ez dira inoiz datu-basean jartzen.','Language'=>'Hizkuntza','Language %s installed successfully.'=>'Hizkuntza %s arrakastaz instalatu da.','Language (optional)'=>'Hizkuntza (aukerakoa)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian (DISALLOW_FILE_MODS ezarrita dago).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian. DISALLOW_FILE_MODS konstantea wp-config.php-n ezarrita dago. Instalatu hizkuntza paketeak eskuz WP-CLI bidez: wp language core install de_DE','Language label'=>'Hizkuntza etiketa','Language Overrides'=>'Hizkuntza Aldaketak','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Hizkuntzen Aldaketak: kudeatu zure .po/.mo fitxategi pertsonalizatuak Lingua Forge UI-rako. Erabili hau plugin fitxategiak zuzenean editatu beharrean — aldaketak bizirauteak iraun dezake.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Hizkuntza paketea instalatzea huts egin du. Hizkuntza jada instalatuta egon daiteke, locale kodea okerra izan daiteke, edo zure zerbitzariak fitxategien idazketa bloke dezake.','Language Setup'=>'Hizkuntza konfigurazioa','Language Switcher'=>'Hizkuntza Aldatzen','Language switcher'=>'Hizkuntzen switcher','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Gaia-oinarritutako kopiak, hizkuntzaren arabera. Eskemak sortu ondoren, txantiloiak hizkuntzaren arabera eguneratzen dira.','Language:'=>'Hizkuntza:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Router-ek ezagutzen dituen hizkuntzak (WordPressen locale paketeak eta oinarrizko hizkuntza). Instalatu hizkuntza pakete gehiago beheko atalean, bidegurutze eta itzulpenetarako gehiago hizkuntza erabilgarri egiteko.','Last 30 days'=>'Azken 30 egun','Last 7 days'=>'Azken 7 egun','Lead paragraph (≤60 w)'=>'Lehen paragrafoa (≤60 hitz)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Utzi modelo eremua hutsik, eta erabil ezazu eraikitako lehenetsia maila horretarako. Lehenetsia testuaren ordezkoa erakusten du.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Utzi hutsik marken izenak eta hizkuntzarekiko ezberdintasunak ez diren terminoa betetzeko, itzultzen garenean.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Utzi hutsik, sarrera hau guztietara aplikatzeko — marka izenak, laburdurak eta beti berdin gordetzeko terminoa.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Utzi hutsik eginez gakoa mantentzen da. Sartu balio berri bat ordezkatzeko.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Utzi hutsik erabiltzeko ezarritako lehenetsia. Gorde aurretik ezarritako aldaketa ezabatzeak lehenetsia berreskuratuko du hurrengo gordetzean.','Legal / Compliance'=>'Juridikoa / Betetze','Legal / Compliance instructions'=>'Lege / Betetze argibideak','Light'=>'Argia','Light (default — fast and cost-effective)'=>'Arina (lehena — azkar eta kostu txikia)','Light (fast and cost-effective — Haiku / Flash)'=>'Argia (azkar eta kostu eraginkorra — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Argia: erabiltzen da meta deskribapenak eta laburpenak sortzeko — azkarra, kostu baxua.','Limit results to pages in the given Lingua Forge language code.'=>'Mugatu emaitzak Lingua Forge hizkuntza kodean dauden orrietan.','Limits'=>'Muga','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge zure WordPress gunean hizkuntza anitzeko bideraketa, AI bidezko itzulpena, hreflang SEO etiketa eta hizkuntzaren switcher gehitzen ditu.','Lingua Forge AI Tools'=>'Lingua Forge AI tresnak','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge-k Gutenberg bi ezaugarri mugatzen du lehenetsian, hizkuntza arteko jokabidea koherente mantentzeko. Aukeratu hemen zuretzat beharrezkoa den Gutenberg / FSE gaitasun osoa izateko.','Lingua Forge Settings'=>'Lingua Forge Ezarpenak','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge-k bi cache geruza independente erabiltzen ditu AI API deien errepikapenak saihesteko. Erabili beheko fitxak bakoitza aztertzeko eta kudeatzeko.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge-k bi modelo maila erabiltzen ditu hornitzaile bakoitzeko:','Lingua Forge — Quick Translate'=>'Lingua Forge — Azkar Itzuli','Lingua Forge — Settings'=>'Lingua Forge — Ezarpenak','link(s)'=>'lotura(ak)','Links'=>'Loturak','Load available languages'=>'Kargatu hizkuntza erabilgarriak','Loading…'=>'Kargatzen…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate bere itzulpen pertsonalak wp-content/languages/loco/ kokatzen ditu — leku hori WP eguneraketak, plugina berrabiarazteak edo Loco Translate ezabatzeak ezabatzen du. Fitxategiak hemen kopiatzeak Lingua Forge i18n-overrides direktorioan jartzen ditu, eta horrek iraun duzuen bitartean mantentzen da, eta automatikoki kargatzen da eskaera bakoitzean.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiatu Segurtasun Gunean','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI ezaugarriak aktibatzeko aukera ematen duen WordPress gaitasun minimoa. Honek multi-autor guneetan murrizten du, Kontribuzioak edo proba kontuak AI bidezko deien kostuak saihesteko. Gainbegiratu ezazu funtzioen arabera linguaforge_required_capability filter bidez.','Maintenance'=>'Mantentze-lanak','Maintenance Tab'=>'Mantentze Fitxa','Make casual'=>'Egin informaleago','Make concise'=>'Egin labur','Make formal'=>'Egin formalago','Mark citations needed'=>'Markatu aipuak behar direla','Max context characters'=>'Testuinguru maximoa','Max hints characters'=>'Gomendioen karaktere maximoa','Max input characters'=>'Max karaktere input','Max output tokens'=>'Max tokens output','Maximum characters accepted from the input field. Default: 8 000.'=>'Sarrerako eremuak onartzen dituen karakter kopururik handiena. Lehenetsia: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'AIri pasatzen zaion edukia, gomendiorik ez dagoenean, hazi testuinguru gisa. Lehenetsia: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Gomendioen eremutik irakurritako karaktere maximoa. Lehenetsia: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Postaren edukia bidali zaion karakter kopururik handiena. 0 ez du mugarik — beti bidaltzen da edukia osoa (gomendatua). Ezarri balio ez-zeroa zure hornitzaileak testuinguru leiho estu bat duenean. Abisua PHP errore erregistroan idazten da edukia moztu denean.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Max tokens kopurua AIk ekoiztu dezakeen itzulpen erantzun batean. Itzulpen bat isilpean moztu bada, handitu balio hau. Lehenetsia: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'AI-k ekoiztu dezakeen token kopururik handiena sortze bakoitzeko. Handitu hori, artikulu osoak moztu gabe geratzen direnean. Lehenetsia: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI-k ekoiztu dezakeen token kopururik handiena itzulpen azkar bakoitzeko. Lehenetsia: 2.000.','Meta Description'=>'Meta Deskribapena','Meta Description, Excerpt Generator'=>'Meta Deskribapena, Laburpen Sortzailea','Minimum role'=>'Gutxieneko rola','Missing pattern name or language.'=>'Patroiaren izena edo hizkuntza falta da.','Mode'=>'Modua','Model'=>'Eredua','Model tier'=>'Modelo maila','Models'=>'Modeloak','Models Tab (General)'=>'Modeloak Fitxa (Orokorra)','Most recent cached block'=>'Azkeneko cacheko blokea','Most recent cached response'=>'Azkeneko cacheko erantzuna','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Baliabide anitzeko bidegurutzeak, SEO meta etiketak, eta AI eduki tresnak WordPress-entzat. Hizkuntza detekzioa, URL bidegurutzeak, hreflang, meta deskribapenak, eta AI-k powered laburpen, meta, eta itzulpen ezaugarriak konbinatzen ditu.','Name displayed in this language. Leave empty to use the source name.'=>'Izena hizkuntza honetan erakutsia. Utzi hutsik itzultzaile izena erabiltzeko.','Navigation'=>'Nabigazioa','Navigation has no content to translate.'=>'Nabigazioak ez du itzultzeko edukiarik.','Navigation not found.'=>'Nabigaziorik ez da aurkitu.','Navigation posts are translated via the Router tab, not this button.'=>'Nabigazio mezuak Router fitxan itzultzen dira, ez botoi honetan.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Nabigazioaren itzulpena AI hornitzaile aktibo baten beharra du. Konfiguratu API giltza API Giltzen fitxan.','Navigations'=>'Nabigazioak','Network error — could not reach the WordPress AJAX endpoint.'=>'Sareko errorea — ezin izan da WordPress AJAX puntura iritsi.','No %s version found in this translation group.'=>'Ez da %s bertsio bat aurkitu itzulpen talde honetan.','No AI provider configured.'=>'AI hornitzaile konfiguratu gabe.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Ez da AI erabilerarik erregistratu aukeratutako leihoan (%s). Aukeratu goiko zabalagoa.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Oraindik ez da AI erabilerarik erregistratu. Behin editore batek itzulpena egin, meta deskribapena sortu edo beste AI ezaugarri bat erabili, totala hemen agertuko da.','No API key configured for this provider.'=>'Ez dago API gako konfiguraturik hornitzaile honetan.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Ez da prestatutako ezarpenik — AI ezaugarriek beren ezarpenak erabiltzen dituzte. Bete beheko Pertsonalizatutako aginduen eremua zure webguneko arau propioak gehitzeko.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Oraindik ez da Loco Translate fitxategirik aurkitu. Itzulpena gordetzen duzunean agertzen da hemen.','No file was selected.'=>'Ez da fitxategirik aukeratu.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Ez dago oraindik filtroarekin bat datorren glossario sarrerarik. Garbitu filtroa guztiz ikusteko edo sartu berri bat gehitzeko behean.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Oraindik ez dago glossario sarrera. Gehitu behean terminologia betetzeko itzulpenetan.','No internal links found to update.'=>'Ez da barruko estekarik egon eguneratzeko.','No language-specific template parts found to map.'=>'Ez da hizkuntza-espezifikoak diren txantiloia zatiak aurkitu mapatzeko.','No navigation references needed updating.'=>'Ez da nabigazio erreferentziarik egon eguneratzeko.','No override files uploaded yet.'=>'Oraindik ez da ordezkaritza fitxategirik kargatu.','No response from provider — check the error log for details.'=>'Hornitzailearen erantzunik ez — egiaztatu errore erregistroa xehetasunak egiteko.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Ez dago bigarren hizkuntzarik konfiguraturik. Instalatu hizkuntza paketea goian, txantiloiak sortzeko aukera emateko.','No source content found to translate.'=>'Ez da itzultzeko iturri edukirik aurkitu.','No source page linked yet.'=>'Oraindik ez dago iturri orririk lotuta.','No template part references needed updating.'=>'Ez da eguneratzeko behar diren txantiloia zatiaren erreferentziarik.','No {lang} translation registered (TRID missing)'=>'Ez dago {lang} itzulpenik erregistratuta (TRID falta)','Notes'=>'Oharra','Notice message'=>'Ohar mezua','Notice settings'=>'Ohar ezarpenak','Oldest cached block'=>'Guztien zaharrena cacheko blokea','Oldest cached response'=>'Guztien zaharrena cacheko erantzuna','Only .mo files are accepted.'=>'Only .mo fitxategiak onartzen dira.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Aukerazko testuingurua editoreentzat (adibidez, "ASIC = Application-Specific Integrated Circuit; ingelesean gorde tekniko testuinguruetan").','Output'=>'Irteera','Output tokens'=>'Irteerako tokenak','overridden'=>'gainditua','Override file deleted.'=>'Ordezkatzeko fitxategia ezabatu da.','Override file uploaded successfully.'=>'Orriaren ordezkoa arrakastaz kargatu da.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Aldatzen du AI lehenetsia Orriko Itzulpenean eta Edukiaren Sortzean. Beste ezaugarri guztiak beti erabiltzen dute lehenetsia globala.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Aldatzen du AI lehenetsia Orriko Itzulpenean eta Edukiaren Sortzean. Gune osoan konfiguratutako prompt-eskakizunak (Ezarpenak → Portaera) beti gehitzen dira eskaera bakoitzean, aukeraketa honetatik independentea.','Overview'=>'Orokorra','Page'=>'Orria','Part'=>'Zatia','Paste a footnote, sentence, or any snippet here…'=>'Itsatsi ohar, esaldi edo zati hau...','Paste text, or select text in the editor first…'=>'Itsatsi testua, edo hautatu testua editorean lehen…','Paste text, or select text on the page first…'=>'Itsatsi testua, edo hautatu testua orrialdean lehen…','Paste your API key…'=>'Itsatsi zure API giltza…','Path prefix — example.com/de/'=>'Bide-izena — example.com/de/','Pattern'=>'Patron','Pattern has no content to translate.'=>'Ez dago itzuli beharreko edukirik patroiak.','Pattern not found.'=>'Ez da patroiarik aurkitu.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroia itzuli eta gorde da. Edukia zure CPT postean kopiatzailearen bidez edo Erabilerako Blokearen sarreran erabili edo Erabilerako Blokearen hasierako puntutzat erabili.','Pattern translation failed.'=>'Patroiaren itzulpena huts egin du.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Post bakoitzeko cache itzulpen AI bidez, meta deskribapenak, laburpenak eta edukia. Beti aktibo — ez da toggle berezirik behar. Sarrera baliogabetzen dira automatikoki edukia edo AI hornitzailea/modelo aldatzen denean. Erabili tresna-barraren "↺ Berriz itzuli" botoia edo sakatu Garbitu behean, API de berria egiteko.','Permalink rules flushed successfully.'=>'Permalinka arauak arrakastaz bideratu dira.','Permission denied.'=>'Baimena ukatua.','Persuasive'=>'Beldurgarria','PHP constant'=>'PHP konstantea','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Terminoak pinatu behar dira itzuli ez daitezen edo beti modu jakin batean itzuli behar direnak (adibidez, marka-izenak, produktuen izenak, akronimoak). Glosarioaren muga AI itzulpen eskaera guztietan inposatzen dira: post itzulpena, meta deskribapena, laburpena, eta FSE txantiloi itzulpena.','Plain language'=>'Hizkuntza arrunta','Please enter some instructions first…'=>'Mesedez, lehenengo argibide batzuk sartu…','Please enter some text first…'=>'Mesedez, lehenengo testu batzuk sartu…','Post'=>'Posta','Post not found.'=>'Posta ez da aurkitu.','Post Types'=>'Post Motak','Prefilled from excerpt. Edit to override.'=>'Aldizkariaren zatitik aurretik bete. Aldatu nahi baduzu, editatu.','Primary Language'=>'Hizkuntza Nagusia','Primary language'=>'Hizkuntza nagusia','Primary language saved.'=>'Hizkuntza nagusia gorde da.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Hizkuntza primarioa: zure edukia idatzitako hizkuntza. Itzulpen guztiak honetatik sortzen dira; aldaketa ez du postak mugitzen edo ezabatzen.','Processing…'=>'Prozesatzen…','Provider'=>'Hornitzailea','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Hornitzaileak ez du testurik itzuli. Egiaztatu WordPress errore erregistroa huts eginaren arrazoi zehatza ikusteko.','Quality'=>'Kalitatea','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (lehentasuna — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kalitatea: erabiltzen da post itzulpen eta edukien sorkuntzarako — kalitate handiagoa, kostu handiagoa.','Quick Translate'=>'Azkar itzulpena','Quick Translation'=>'Azkar Itzulpena','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Azkar Itzulpena erabilia da zatitxo/modu laburretan — pasarte laburrek eskaeraz itzultzen dira tresnabarra, editorea edo blokea popoverak erabiliz. Konfigurazio arinagoa erabiltzen du, orri osoaren itzulpenetik, erantzunak azkarrago eta kostu txikiagoa izan dadin.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg-en canLockBlocks berriro aktibatzen du. Edizio txantiloietan erabilgarria da, kolaboratzaileek bloke zehatzak mugitu edo ezabatu ez ditzaten.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Re-enables supportsTemplateMode. Oinarrizko lan-fluxuak, non post mailako txantiloiak ukitzen diren, helburu da.','Re-generates and updates the cached result.'=>'Emaitza cache-a berriro sortzen eta eguneratzen du.','Re-scan'=>'Birbideratu','Re-scanning…'=>'Berrikuspen…','Re-translate'=>'Berriz itzuli','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Bisitzaileak birzirkulatu bere nabigatzailearen Accept-Language goiburua oinarrituta','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'hobetu gehiago — adibidez "laburtu egin" edo "erabili tonu formal bat"…','Refine further:'=>'Hobetu gehiago:','Refinement'=>'Hobekuntza','Refinement failed — please try again.'=>'Hobekuntza huts egin da — mesedez saiatu berriro.','Refining…'=>'Hobetu…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPressen berridazketa arauak berriro sortzen ditu URL-aren aurkezpenak, hizkuntza-espezifikoak eta artxibo berridazketak bat etortzeko. Oinarrizko hizkuntza aldatzean edo hizkuntza berriak gehitzean beharrezkoa.','Remove stored key'=>'Ezabatu gakoa gordeta','Report an issue on GitHub'=>'Txostena GitHub-en','Request failed — please try again.'=>'Eskakizuna huts egin du — mesedez saiatu berriro.','Request failed.'=>'Eskakizuna huts egin du.','Request failed. Check your connection.'=>'Eskakizuna huts egin du. Egiaztatu zure konexioa.','Request failed. Please try again.'=>'Eskakizuna huts egin du. Saiatu berriro.','Requests'=>'Eskaerak','Reset'=>'Berrezarri','Result will appear here…'=>'Emaitza hemen agertuko da…','Retranslate'=>'Itzuli berriro','Retranslating…'=>'Itzultzen berriro…','Review carefully — links and slugs not updated.'=>'Aztertu arretaz — estekak eta slugak ez dira eguneratu.','Review translation before applying'=>'Aztertu itzulpena aplikatu baino lehen','Revise'=>'Berrikusi','Revision'=>'Berrikuntza','Revision Type'=>'Berrikuntza mota','Router'=>'Router','Router Tab'=>'Router-aren Fitxa','Save Debug Setting'=>'Gorde Debug Konfigurazioa','Save Router Settings'=>'Gorde Router-ezintzak','Save Settings'=>'Gorde Ezarpenak','Save the post to persist changes.'=>'Gorde mezua aldaketak gorde ahal izateko.','Save Uninstall Setting'=>'Gorde Desinstalazio Ezarpena','Saved to the meta description field when you apply.'=>'Gorde meta deskribapen eremuan aplikatzen duzunean.','Scan failed: '=>'Eskaneaketa huts egin du: ','Scan request failed. Please try again.'=>'Eskaneatzeko eskaera huts egin du. Saiatu berriro.','Scanning posts for broken language links…'=>'Hitz egiten ari diren postak hizkuntza loturak hausten saiatzen…','Search'=>'Bilaketa','Search Results'=>'Bilaketa emaitzak','Security check failed — file path is not permitted.'=>'Segurtasun kontrola huts egin du — fitxategiaren bidea ez da baimendua.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Hautatu hizkuntza, bere FSE txantiloiak, zatiak eta nabigazio menuak kudeatzeko.','Select language'=>'Hizkuntza hautatu','SEO character-count info'=>'SEO karakter-kopurua informazioa','Server setup (subdomain)'=>'Zerbitzariaren konfigurazioa (azpigunea)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'AIren portaera lehenetsia ezartzen du webgune osoan. Post bakoitzak aldatu dezake Translatio eta Eduki Sortzailearen bidez Lingua Forge meta kutxa erabiliz.','Settings'=>'Ezarpenak','Settings saved.'=>'Ezarpenak gorde dira.','Show home link'=>'Erakutsi hasierako esteka','Shown when no translation exists for the visitor\'s language.'=>'Ez dago itzulpenik bisitariaren hizkuntzarako.','Single'=>'Bakarra','Single %s'=>'Bak %s','Single: %s'=>'Bak: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'AI eskaerak UTC egunean (biak Toolbar itzulpenak eta blokeko berrikuspenak) muga. Kontagailua UTC erdian berritzen da. Utzi 0, muga desgaitu nahi baduzu.','Size'=>'Tamaina','Some link fixes failed.'=>'Etxe batzuk konponketak huts egin dute.','Some nav ref fixes failed.'=>'Nabigazio erreferentziak konponketak huts egin dute.','Some part fixes failed.'=>'Atal batzuk konponketak huts egin dute.','Some parts could not be created.'=>'Etxe batzuk ezin izan dira sortu.','Some templates could not be created.'=>'Etxe batzuk ezin izan dira sortu.','Some translations failed.'=>'Itzulpen batzuk huts egin dute.','Source file not found.'=>'Iturri fitxategia ez da aurkitu.','Source lang'=>'Iturri hizkuntza','Source language'=>'Hizkuntza iturriaren','Source term'=>'Iturri terminoa','Standard'=>'Estándarra','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standardak ezaugarri bakoitzaren tenperatura egokituaren erabilera du: Itzulpena T=0.2 ( zehatza), Azkar Itzulpena T=0.4, Eduki Sortzailea T=0.6 (kreatiboa). Beste aurrekoak tenperatura finkoa aplikatzen du ezaugarri guztietan.','Status'=>'Egoera','Status / Actions'=>'Egoera / Ekintza','Storytelling'=>'Istorioak','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Lege, araudi, mediku edo tekniko edukiaren gordetzeko modua. Aktibatzen denean, AI ezaugarri bakoitzak tenperatura baxu bat erabiltzen du eta behean gehitzen du sistema prompt-aren azpian — terminologia, artikulu zenbakiak, unitateak, marka izenak eta araudi hizkuntza bertan bertan gordetzen dira, ez paragrafatuak.','Structured Outline'=>'Eskema antolatu','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Azpi-domein moduak zure web zerbitzariari eskatzen dio azpi-domein hizkuntzak (adibidez, de.example.com) WordPress instalazio honetara zuzentzea. Moduak aldatzean, permalinka arauak bota eta cache-ak garbitu. Zure hasierako URL-an www badago (adibidez, www.example.com), lf_base_domain iragazkia erabili domeinaren goiko maila ezkutatzeko, azpi-domeinak era egokian eraikitzeko.','Subdomain — de.example.com/'=>'Azpi-domein — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Hornitzaile onartuak: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Batek baino gehiagok ez dute aktiboa aldi berean. Hautatu aktibo dagoen hornitzailea Orokorreko fitxan.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ezaugarri bakoitzeko','Target lang'=>'Helburu hizkuntza','Target Language'=>'Hizkuntza Helburu','Target language'=>'Helburu hizkuntza','Target term'=>'Helburu terminoa','Target: 140–160 chars for optimal SERP display'=>'Helburua: 140–160 karakter SERP-n ondo erakusteko','Technical'=>'Teknikoa','Technical / Scientific'=>'Teknikoa / Zientzia','Technical / Scientific instructions'=>'Tekniko / Zientziazko argibideak','Template "%s" already exists.'=>'"%s" jada existitzen da.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'"{expected}" izeneko txantiloi ez da existitzen — sortu lehenengo Gune Editorean.','Template has no content.'=>'Txantiloian ez dago edukirik.','Template mode'=>'Txantiloi modua','Template not found or not stored in the database.'=>'Txantiloia ez da aurkitu edo ez da datu-basean gordeta.','Template part "%s" already exists.'=>'"%s" zatia jada existitzen da.','Template part has no content.'=>'Ez dago edukirik txantiloia zatian.','Template part not found or not stored in the database.'=>'Ez da txantiloia zatiaren erroa edo ez da gordeta datu-basean.','Template Parts'=>'Txantiloien Zatiak','Templates'=>'Txantiloiak','Test connection'=>'Testatu konexioa','Testing…'=>'Testing…','Text domain / locale'=>'Testu domeinua / hizkuntza','Text to translate'=>'Itzuli beharreko testua','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'API Erantzun Cacheak AI eskaeraren emaitza gordetzen du — itzulpena, meta deskribapena, laburpena, eta edukia — sarrera hash baten bidez (edukia, hizkuntza pareta, hornitzailea, modelo). Eskari jarraituak, sarrerak berdinak badira, cachetik ematen dira API de beharrik gabe. Cachea ez da Itzulpen Memoria: Itzulpen Memoria bloke mailakoa da eta partekatua da post guztien artean; API Erantzun Cachea ez da ezaugarri mailakoa eta post bakoitzeko giltza du.','The editor did not accept the content — please try again.'=>'Editoreak ez zuen edukia onartu — mesedez saiatu berriro.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Arin mailak model azkarrena erabiltzen du goiko Modeloak taulan konfiguratutako moduan (lehena: Haiku / Flash). Aldatu Kalitatera, zatitxoetan orri osoaren itzulpenaren zehaztasuna behar duzunean.','The phrase as it appears in the source text.'=>'Iturri testuan agertzen den esamena.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Hizkuntza nagusia beti zerbitzatzen da zure gunearen erroan — ez URL aurrizkia bide moduan, ez hizkuntza azpian domeinua moduan. Beste hizkuntzak edo /lang/ bide aurrizkia (adibidez example.com/de/) edo hizkuntza azpian domeinua (de.example.com) erabiltzen dituzte, beheko URL egitura ezarpenaren arabera.','The source page has no footnotes.'=>'Iturri orriaren ohar-oinik ez dago.','The upload failed — please try again.'=>'Kargatzea huts egin du — saiatu berriro.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Ohar-oin hauek iturri orritik datoz eta hemen agertzen dira erreferentzia gisa soilik. Gehitu hauek orri honetan blokea editorea erabiliz.','This is the source page. Footnotes are edited directly in the block editor.'=>'Hau da iturri orria. Ohar-oinak zuzenean editatzen dira blokea editorean.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Gakoa hau une honetan zerbitzariko %s batek hornitzen du eta ezin da hemen ezabatu. Sartu gakoa goian gainean eta datu-baseko balio batekin ordezkatu.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: modelo bat lehenetsira berrezartzeko, garbitu eremua eta gorde.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Erabili nahi duzun enkriptazio sekretu pertsonalizatua (wp_salt balioa lortzeaz gain), gehitu hau wp-config.php-ra:','Today'=>'Gaur','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token kontsumoa ezaugarri, hornitzaile eta ereduen arabera. AI deien arruntean erregistratzen da; Test konexio pingak ez dira barne hartzen, totala oker ez dadin. Taula azkarra egunero biltzen du — aukeratu beheko leihoa ikusteko.','Tone'=>'Tona','tone'=>'tonu','Tone:'=>'Tonua:','Too many AI requests. Please retry in %d seconds.'=>'AI eskaera gehiegi. Saiatu berriro %d segundo barru.','Total'=>'Guztira','Total tokens'=>'Token guztira','Translate'=>'Itzuli','Translate / Revise'=>'Itzuli / Berrikusi','Translate / Revise block'=>'Bloke itzuli / Berrikusi','Translate all'=>'Itzuli guztiak','Translate chunk'=>'Itzuli zatia','Translate Content'=>'Itzuli Edukia','Translate missing'=>'Missing itzuli','Translate page…'=>'Orria itzuli…','Translated content'=>'Itzulitako edukia','Translated Names'=>'Izendapenak itzuli','Translated title'=>'Itzulitako izenburua','Translated to:'=>'Itzuli da:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Itzuli da. Ikuskaritza-sarean berrikusi — lotura barneak, nabigazio URL-ak eta txantiloiaren slug-ak ez dira automatikoki eguneratzen.','Translating…'=>'Itzultzen…','Translation'=>'Itzulpena','Translation Caching'=>'Itzulpenaren cachea','Translation found but permalink could not be generated'=>'Aurkitu da translatzea baina permalink-a ezin izan da sortu','Translation Limits'=>'Itzulpen Muga','Translation Limits & Behavior'=>'Itzulpenaren mugak eta portaera','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Itzulpenaren mugak: kontrolatu zein erabiltzaile rolek aktibatu dezaketen AI itzulpena, eta ezarri hilean tokens kopurua. Aurrez aurreko kopurua gaindituz, AI deien erabilera etengo da hilabetea berritzen den arte.','Translation Memory'=>'Itzulpen Memoria','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Itzulpen Memoriak AI emaitzak cacheatzen ditu edukien hash, hizkuntza bikote, hornitzaile eta modelaren arabera. Post bat editatzeak cachea baliogabetzen du, beraz hurrengo itzulpenak emaitza fresko bat jasoko du.','Translation Memory cleared. %d cached block was removed.'=>'Itzulpen Memoria garbitu da. %d cacheatutako blokea kendu da.' . "\0" . 'Itzulpen Memoria garbitu da. %d cacheatutako bloke kendu dira.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Itzulpen Memoria: edukien hasharen arabera post guztia itzuli duena gordetzen du. Garbitu hori, post guztiak berriro itzuli nahi badituzu, edukiak aldatu edo ez.','Translation workflow'=>'Itzulpenaren lan-fluxua','Translation, Content Generator'=>'Itzulpena, Eduki Sortzailea','Type'=>'Mota','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Desinstalazio Portaera','Uninstall setting saved.'=>'Desinstalazio ezarpena gorde da.','unknown error'=>'Errorea ezezaguna','Unknown provider.'=>'Hornitzaile ezezaguna.','Up'=>'Gora','Upload .mo file'=>'Kargatu .mo fitxategia','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Gorde konpilatutako .mo fitxategiak hirugarren aldeko pluginen testuak ordezkatzeko, esaterako, VikBooking itzulpen pertsonalizatua "etxea" ordez "gela" erabiltzen duena. Fitxategiak WordPress izenburuaren arauak jarraitu behar ditu: {textdomain}-{locale}.mo (adibidez, vikbooking-ca.mo). Uploads karpetan gordetzen dira eta plugin eguneraketekin iraun dezakete.','Upload Override'=>'Kargatu Ordezkaketa','URL could not be mapped to a post — check the link target exists'=>'URL ez da mapatu post batera — egiaztatu helburu lotura existitzen dela','URL structure'=>'URL egitura','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL egitura: bide-berri modua (adibide.com/de/) ez du zerbitzariko aldaketarik behar. Azpiburu modua (de.adibide.com) DNS erregistro zabaldu bat, SSL ziurtagiri zabaldu bat eta zerbitzariaren konfigurazio aldaketa bat behar du — ikusi Zerbitzariaren konfigurazio gida.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Erabili orriaren goialdeko fitxak konfigurazio bakoitza egiteko. Router fitxan egindako aldaketak berehala aplikatzen dira; AI gakoak eta ereduen konfigurazioak hurrengo AI eskaeran aplikatuko dira.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula terminologikoaren kudeaketa erabiltzaileak hizketa bikoitzeko. Sarrera hauek gehitzen dira itzulpen sistemaren prompt-ean, AI-k termino hobesien erabilera jarraitzeko — dominen hizkuntzako lexikoan oso garrantzitsua ("kWp", "PPA", "interkonexio puntua"), markaren izenak ez dira itzuli behar, eta araudi estandarizatuen formulazioak. Bi hizketa eremuak aukera librekoa dira: utzi "Iturri hizkuntza" hutsik sartu nahi duzun hizkuntzaren araberakoa izan gabe; utzi "Helburu hizkuntza" hutsik, guztietara aplikatzeko.','Using custom meta description.'=>'Metadatu pertsonalizatu bat erabiltzen','View'=>'Ikusi','View built-in default'=>'Ikusi lehenetsia','View details'=>'Ikusi xehetasunak','View Lingua Forge details'=>'Ikusi Lingua Forge xehetasunak','Visit plugin site'=>'Bisita ezarpenen webgunea','Warning:'=>'Abisua:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Debug log-ak aktibatuta dagoenean (beheko toggle bidez edo wp-config.php-n LINGUAFORGE_AI_DEBUG definituz), Itzulpen eta FSE txantiloi itzulpen ezaugarriak AI prompt eta erantzunak diskoan idazten dituzte arazteak egiteko. Erabili atal hau irteera hori monitorizatzeko eta garbitu behar duzunean — fitxategiak azkar handitzen dira orri handietan. Konfiguratu helbide direktorioa linguaforge_debug_dir iragazkiaren bidez.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Gaituta, lehenengo aldiz bisitatzaileek hizkuntza cookiea edo URL-an hizkuntza aurrebista ez badute, hurbilen dagoen hizkuntza bertsiora birzirkulatuko dira. Birzirkulazioa saihesten da nabigatzailearen hizkuntza aktiboen artean ez badago. Bisitari batek hizkuntza bat hautatzen duenean, cookieak lehentasuna hartzen du eta nabigatzailearen goiburua ez da kontuan hartzen bisita guztietan.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Zein modelo maila erabili itzulpen osoarentzat. Kalitatea goian ezarritako Modelo taulan konfiguratutako modeloa erabiltzen du eta gomendatzen da zehaztasun handiko, luzeak diren itzulpenetan. Aldatu Argira, azkartasuna edo kostua lehentasuna bada eta edukia laburra bada.','WP-CLI reference'=>'WP-CLI erreferentzia','Write AI prompts and responses to disk for troubleshooting'=>'AI prompt eta erantzunak diskoan idaztea arazteak egiteko','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Gakoak ere definitu ditzakezu konstante edo ingurune aldagaitzat (adibidez, wp-config.php-n). Iturri horiek automatikoki erabiltzen dira datu-baseko gakoa ez dagoenean oinarrizko baliabide gisa.','You do not have permission to manage these settings.'=>'Ez duzu baimenik ezarpen hauek kudeatzeko.','You do not have permission to read this post.'=>'Ez duzu baimenik irakurtzeko posta hau.','{n} stale path(s)'=>'{n} bide zahar(ra)','— Any source language —'=>'— Edozein iturri hizkuntza —','— Any target language —'=>'— Edozein helburu hizkuntza —','— Any target —'=>'— Edozein helburu —','— Any —'=>'— Edozein —','— auto-detect —'=>'— auto-detektatu —','— select a language —'=>'— hautatu hizkuntza —','— toggle in Settings → Behavior.'=>'— toggle Ezarpenetan → Portaeran.','← Back'=>'← Atzera','↑ Detected from current post'=>'↑ Uneko postetik detektatua','↺ Re-translate'=>'↺ Berriro itzuli','↺ Refine'=>'↺ Hobetu','↺ Refresh'=>'↺ freskatu','↺ Refreshing…'=>'↺ Freskatu…','⚠ Borderline'=>'⚠ Muga-lerroa','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ {lang} ez da aurkitu. Ziurtatu itzuli diren post guztiek hizkuntza metadatuan {lang} ezarrita dutela.','⚠ No changes'=>'⚠ Ez da aldaketarik','⚠ No changes — re-scan?'=>'⚠ Ez da aldaketarik — berriro eskaneatu?','✅ Fixed ({n})'=>'✅ Konponduta ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Ez da hautsi edo txantiloiak ez datoz bat aurkitu. Ikusi <strong>{scanned}</strong> post eta orri — guztiak ondo daude. Txantiloi zatien loturak (goiburua, oinarria, alboko barra) ez dira hemen sartzen — erabili Fix Template Parts botoia horiek banan banan egiaztatzeko.','✅ Template fixed'=>'✅ Txantiloa konponduta','✓ All parts created.'=>'✓ Atal guztiak sortu dira.','✓ All templates created.'=>'✓ Txantiloi guztiak sortu dira.','✓ All translated.'=>'✓ Itzulpen guztiak egin dira.','✓ Configured'=>'Konfiguratu da','✓ Connection OK'=>'✓ Konexioa ondo','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Edukia sortu da — ikusi gainjarri hori berrikusteko, hobetu, eta aplikatzeko.','✓ Done'=>'✓ Eginda','✓ Enabled'=>'✓ Aktibatuta','✓ Good length'=>'✓ Luzera ona','✓ In safe storage'=>'✓ Segurtasun gunean','✓ Language installed.'=>'✓ Hizkuntza instalatu da.','✓ Links fixed.'=>'✓ Estekak konponduta.','✓ Nav refs fixed.'=>'✓ Nabigazio erreferentziak konponduta.','✓ Parts fixed.'=>'✓ Atalak konponduta.','✓ Pattern translated.'=>'✓ Patroi itzulita.','✓ Refined — review the updated draft above.'=>'✓ Hobetu da — begiratu goiko zirriborro eguneratua.','✓ Translation saved'=>'✓ Itzulpena gorde da','✗ Disabled'=>'✗ Desaktibatuta','✗ Error:'=>'✗ Akatsa:','✗ Failed:'=>'✗ Huts egin du: ','✗ Not configured'=>'Ez da konfiguratu','✗ Too long'=>'✗ Oso luze','✗ Too short'=>'✗ Oso laburra','❌ Failed'=>'❌ Huts egin du','📄 Wrong template'=>'📄 Txantiloi okerra','📍 Stale path (page moved)'=>'📍 Bide zahar (orria mugituta)']];
